from pathlib import Path
import subprocess, json, shlex
pdfs=sorted(Path('related_work').glob('*.pdf'))
summary={}
for pdf in pdfs:
    entry={}
    try:
        out=subprocess.run(['pdfinfo', str(pdf)], capture_output=True, text=True, timeout=20)
        entry['pdfinfo']=out.stdout[:3000] if out.returncode==0 else out.stderr[:1000]
    except Exception as e:
        entry['pdfinfo_error']=str(e)
    try:
        out=subprocess.run(['pdftotext', '-f', '1', '-l', '3', str(pdf), '-'], capture_output=True, text=True, timeout=20)
        txt=out.stdout.replace('\x0c','\n')
        entry['sample_text']=txt[:4000]
        entry['pdftotext_returncode']=out.returncode
        if out.stderr:
            entry['pdftotext_stderr']=out.stderr[:1000]
    except Exception as e:
        entry['pdftotext_error']=str(e)
    summary[str(pdf)]=entry
print(json.dumps(summary, indent=2))
